<template>
  <section class="page">
    <div class="page-heading"><div><h2>Temps de l’équipe</h2><p class="muted">Présences, planning, anomalies et heures supplémentaires à traiter.</p></div><button class="button" @click="load">Actualiser</button></div>
    <div v-if="error" class="alert error">{{ error }}</div><div v-if="notice" class="alert success">{{ notice }}</div>
    <div class="card toolbar"><label>Semaine du <input type="date" v-model="from" @change="loadSchedule"></label><label>Au <input type="date" v-model="to" @change="loadSchedule"></label><label>Département <select v-model="departmentId" @change="loadSchedule"><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.nom }}</option></select></label></div>
    <div class="card"><h3>Présence du jour</h3><div class="table-wrap"><table><thead><tr><th>Employé</th><th>Dernier pointage</th><th>Heure</th><th>État</th></tr></thead><tbody><tr v-for="row in presence" :key="row.employee.id"><td>{{ row.employee.prenom }} {{ row.employee.nom }}</td><td>{{ row.latest?.sens || '—' }}</td><td>{{ row.latest ? dateTime(row.latest.dateHeure) : '—' }}</td><td><span class="badge">{{ row.state }}</span></td></tr><tr v-if="!presence.length"><td colspan="4" class="empty">Aucune présence à afficher.</td></tr></tbody></table></div></div>
    <div class="card"><h3>Planning de l’équipe</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Employé</th><th>Horaire</th><th>Type</th></tr></thead><tbody><tr v-for="row in schedule" :key="row.id"><td>{{ date(row.date) }}</td><td>{{ employeeName(row.employeId) }}</td><td>{{ row.heureDebut }} – {{ row.heureFin }}</td><td>{{ row.type }}</td></tr><tr v-if="!schedule.length"><td colspan="4" class="empty">Aucun planning sur cette période.</td></tr></tbody></table></div></div>
    <div class="detail-grid"><article class="card"><h3>Anomalies ouvertes</h3><div v-for="item in anomalies" :key="item.id" class="notification-item"><strong>{{ date(item.date) }} · {{ item.type }} · {{ employeeName(item.employeId) }}</strong><span>{{ item.commentaire }}</span><div class="actions"><button class="button" @click="treatAnomaly(item,'justifier')">Justifier</button><button class="button" @click="treatAnomaly(item,'corriger')">Marquer corrigée</button><button class="button" @click="treatAnomaly(item,'ignorer')">Ignorer</button></div></div><p v-if="!anomalies.length" class="empty">Aucune anomalie ouverte.</p></article>
      <article class="card"><h3>Heures supplémentaires à valider</h3><div v-for="item in overtimeRequests" :key="item.id" class="notification-item"><strong>{{ date(item.date) }} · {{ employeeName(item.employeId) }} · {{ duration(item.minutes) }}</strong><span>{{ item.motif }}</span><div class="actions"><button class="button primary" @click="decide(item,'valider')">Valider</button><button class="danger-button" @click="decide(item,'refuser')">Refuser</button></div></div><p v-if="!overtimeRequests.length" class="empty">Aucune demande à valider.</p></article></div>
    <div class="card"><h3>Ajouter / corriger un pointage</h3><p class="muted">Le pointage d’origine reste conservé. Le motif est obligatoire.</p><form class="form-grid" @submit.prevent="correctPunch"><label>Employé <select v-model="correction.employeId" required><option value="">Choisir</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.prenom }} {{ e.nom }}</option></select></label><label>Pointage d’origine (facultatif) <input type="number" v-model="correction.pointageOrigineId" placeholder="ID à corriger"></label><label>Date et heure <input type="datetime-local" v-model="correction.dateHeure" required></label><label>Sens <select v-model="correction.sens"><option>ENTREE</option><option>SORTIE</option></select></label><label class="full">Motif <input v-model="correction.motif" required maxlength="1000"></label><button class="button primary" :disabled="busy">Enregistrer le pointage</button></form></div>
  </section>
</template>
<script setup>
import { onMounted, ref } from 'vue'
import api from '@/api/axios'
import { formatApiError } from '@/utils/errors'
const employees=ref([]),departments=ref([]),presence=ref([]),schedule=ref([]),anomalies=ref([]),overtimeRequests=ref([]),departmentId=ref(''),error=ref(''),notice=ref(''),busy=ref(false)
const today=new Date(),from=ref(dateInput(addDays(today,-((today.getDay()+6)%7)))),to=ref(dateInput(addDays(today,6-((today.getDay()+6)%7))))
const correction=ref({employeId:'',pointageOrigineId:'',dateHeure:'',sens:'ENTREE',motif:''})
function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}function dateInput(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function date(v){return v?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'}).format(new Date(`${v}T12:00:00`)):'—'}function dateTime(v){return new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v))}function duration(n){return `${Math.floor((Number(n)||0)/60)} h ${String((Number(n)||0)%60).padStart(2,'0')}`}
function employeeName(id){const e=employees.value.find(x=>Number(x.id)===Number(id));return e?`${e.prenom} ${e.nom}`:`Employé #${id}`}
async function load(){error.value='';try{employees.value=(await api.get('/employes')).data;const ids=new Map();for(const e of employees.value){const a=e.affectationCourante||{};const id=a.departementId??a.departement?.id;if(id!=null)ids.set(String(id),{id,nom:a.departement||a.departementNom||`Département ${id}`})}departments.value=[...ids.values()];if(!departmentId.value&&departments.value.length)departmentId.value=departments.value[0].id;const requests=await Promise.all([api.get('/anomalies',{params:{statut:'OUVERTE'}}),api.get('/heures-sup',{params:{statut:'DEMANDEE'}})]);anomalies.value=requests[0].data;overtimeRequests.value=requests[1].data;await Promise.all([loadSchedule(),loadPresence()])}catch(e){error.value=formatApiError(e)}}
async function loadSchedule(){if(!departmentId.value)return;try{schedule.value=(await api.get(`/departements/${departmentId.value}/planning`,{params:{du:from.value,au:to.value}})).data}catch(e){error.value=formatApiError(e)}}
async function loadPresence(){const todayString=dateInput(new Date());presence.value=await Promise.all(employees.value.map(async employee=>{try{const rows=(await api.get(`/employes/${employee.id}/pointages`,{params:{du:todayString,au:todayString}})).data;const latest=[...rows].sort((a,b)=>new Date(b.dateHeure)-new Date(a.dateHeure))[0];return {employee,latest,state:latest?.sens==='ENTREE'?'Présent · entrée ouverte':latest?.sens==='SORTIE'?'Sorti':'Pas de pointage'}}catch{return {employee,state:'Indisponible'}}}))}
async function decide(item,action){try{await api.post(`/heures-sup/${item.id}/${action}`);notice.value=`Demande ${action==='valider'?'validée':'refusée'}.`;overtimeRequests.value=overtimeRequests.value.filter(x=>x.id!==item.id)}catch(e){error.value=formatApiError(e)}}
async function treatAnomaly(item,action){const commentaire=window.prompt('Commentaire obligatoire pour tracer le traitement :');if(!commentaire?.trim())return;try{await api.post(`/anomalies/${item.id}/${action}`,{commentaire});notice.value='Anomalie traitée.';anomalies.value=anomalies.value.filter(x=>x.id!==item.id)}catch(e){error.value=formatApiError(e)}}
async function correctPunch(){busy.value=true;try{const payload={...correction.value,employeId:Number(correction.value.employeId),pointageOrigineId:correction.value.pointageOrigineId?Number(correction.value.pointageOrigineId):null,dateHeure:new Date(correction.value.dateHeure).toISOString()};await api.post('/pointages/corrections',payload);notice.value='Pointage enregistré dans l’historique.';correction.value={employeId:'',pointageOrigineId:'',dateHeure:'',sens:'ENTREE',motif:''};await loadPresence()}catch(e){error.value=formatApiError(e)}finally{busy.value=false}}
onMounted(load)
</script>
